fn land_plan(r:&Path,i:&str,c:&Value,base:&str,goal:&str,sp:&Value,request:Option<&str>)->Result<Value>{let cs=build_native(r,c,i,base,goal,sp)?;let body=cs.iter().map(|c|{let mut c=c.clone();for k in ["id","agent","branch","actionOutputs"]{c.as_object_mut().unwrap().remove(k);}if c["kind"]=="investigate"{c.as_object_mut().ok_or_else(||Error::new("investigate draft invalid"))?.remove("goal");}Ok(format!("```json\n{}\n```",serde_json::to_string(&c)?))}).collect::<Result<Vec<_>>>()?.join("\n\n");let version=if let Some(sid)=request{crate::session::land_for(r,i,&body,sid)?}else{crate::session::land(r,i,&body)?};Ok(json!({"round":i,"base":base,"state":"Planning","held":true,"contracts":cs,"draft":body,"version":version}))}
pub fn command(r:&Path,sub:&str,args:&[String],o:&Value)->Result<Value>{if !["new","plan","go","run","work"].contains(&sub){return Err(Error::usage("round subcommand must be new|plan|go|run|work"))}if let Some(p)=o.get("poke"){util::rel(p.as_str().ok_or_else(||Error::usage("poke requires a path"))?)?;}if let Some(ps)=o.get("poke-exact"){let ps=ps.as_str().ok_or_else(||Error::usage("poke-exact requires comma-separated paths"))?;if ps.split(',').count()>4096{return Err(Error::usage("too many poke-exact paths"))}for p in ps.split(','){util::rel(p)?;}}retry_limit(o)?;let mut c=config::read(r)?;if let Some(model)=o.get("model"){let model=model.as_str().filter(|s|!s.is_empty()).ok_or_else(||Error::usage("model requires a nonempty ID"))?;if c.get("round").is_none(){c["round"]=json!({})}if !c["round"].is_object(){return Err(Error::new("round configuration must be an object"))}c["round"]["model"]=json!(model);}if c.get("round").is_some_and(|r|!r.is_object()){return Err(Error::new("round configuration must be an object"))}let i=id(&c)?;let _lock=util::FileLock::take(&r.join(".fugue/round-operation.lock"))?;merge::recover(r)?;match sub{"go"=>{crate::session::versions(r,&i)?;if let Some(expected)=o.get("expected-round"){if expected.as_str()!=Some(i.as_str()){return Err(Error::new("approval round changed after display; review the current draft"))}}if !args.is_empty(){return Err(Error::usage("round go accepts no positional arguments"))}let (b,goal)=intent(r,&i)?;let a=journal::read(r,"round")?;let phase=a.iter().rev().find(|r|r.event["t"]=="round/state"&&r.event["round"]==i&&r.event["to"]=="Planning").map(|r|r.seq).ok_or_else(||Error::new("round has no current Planning phase"))?;let e=a.iter().rev().find(|r|r.seq>phase&&r.event["round"]==i&&r.event["t"]=="holder/distill").map(|r|&r.event).ok_or_else(||Error::new("current Planning phase has no draft to approve"))?;if let Some(expected)=o.get("expected-digest"){let expected=expected.as_str().filter(|s|s.len()==16&&s.bytes().all(|b|b.is_ascii_hexdigit())).ok_or_else(||Error::usage("expected-digest must be 16 hex digits"))?;if e["digest"]!=expected{return Err(Error::new("approval batch changed after display; review the new draft"))}}let body=s(e,"body")?;if h(body)!=s(e,"digest")?{return Err(Error::new("draft digest mismatch"))}let cs=build_native(r,&c,&i,&b,&goal,&Value::String(body.into()))?;issue(r,&i,&b,&cs,true,o)},"work"=>{if !args.is_empty(){return Err(Error::usage("round work accepts no positional arguments"))}work(r,&i,&c,o)},_=>{let goal=args.first().filter(|s|!s.is_empty()).ok_or_else(||Error::usage("round requires a goal"))?;if args.len()!=1{return Err(Error::usage("goal must be one argument"))}if goal.len()>1024*1024||goal.contains('\0'){return Err(Error::usage("goal invalid or oversized"))}let state=st(r,&i)?;if state!="Idle"&&(sub!="plan"||state!="Planning"){return Err(Error::new(format!("round already started: {state}")))}let g=Git::open(r)?;let pinned=pinned_intent(r,&i)?;if pinned.as_ref().is_some_and(|(_,g)|g!=goal){return Err(Error::new("round goal differs from its durable pinned intent; resume the original goal"))}let base=if let Some((b,_))=&pinned{b.clone()}else if state=="Idle"{g.resolve("refs/heads/main")?.ok_or_else(||Error::new("main has no base commit"))?}else{return Err(Error::new("started round has no pinned intent"))};let mut sp=split(&c,o)?;let real=o["live"]==true||o.get("wire-in").is_some();if !real{build_native(r,&c,&i,&base,goal,&sp)?;}if state=="Idle"{let l=journal::Lock::take(r,"round")?;let mut es=vec![];if pinned.is_none(){let b=serde_json::to_string(&json!({"goal":goal}))?;es.push(json!({"t":"round/intent","round":i,"base":base,"digest":h(&b),"body":b}));}es.push(json!({"t":"round/state","round":i,"from":"Idle","to":"Planning"}));journal::preflight_locked(&l,&es)?;journal::append_many_locked(&l,es)?;}if sub=="plan"{if real&&o["judge"]!=true{let mut a=o.clone();a["goal"]=json!(goal);a["protocol"]=json!("holder");a["plan_path"]=json!(format!("plans/{i}.md"));let d=model::drive(r,"round",&a)?;if d["done"]!=true{return Ok(json!({"round":i,"state":"Planning","ok":false,"driver":d}))}let body=plan_artifact(r,&i,s(&d,"session")?)?.ok_or_else(||Error::new("holder did not hand in a plan artifact or inline plan"))?;sp=json!(body);}land_plan(r,&i,&c,&base,goal,&sp,None)}else{let cs=build_native(r,&c,&i,&base,goal,&sp)?;let a=issue(r,&i,&base,&cs,false,o)?;if sub=="new"{Ok(a)}else{work(r,&i,&c,o)}}}}}
pub fn say(r:&Path,args:&[String],o:&Value)->Result<Value>{if args.is_empty()||args.len()>256{return Err(Error::usage("say requires a message"))}let text=args.join(" ").trim().to_owned();if text.is_empty()||text.len()>1024*1024||text.contains('\0'){return Err(Error::usage("say message invalid or oversized"))}let c=config::read(r)?;let i=id(&c)?;let _l=util::FileLock::take(&r.join(".fugue/round-operation.lock"))?;let state=st(r,&i)?;if !["Idle","Planning"].contains(&state.as_str()){return Err(Error::new(format!("say accepts Idle discussion or Planning revision only; current state {state}")))}let real=o["live"]==true||o.get("wire-in").is_some();let rr=journal::read(r,"round")?;let saved=if real{rr.iter().rev().find(|q|q.event["t"]=="runtime/start").filter(|q|q.event["state"]["roundId"]==i&&q.event["state"]["runtime"]==text&&!rr.iter().any(|e|e.event["t"]=="say/end"&&e.event["session"]==q.event["session"]))}else{None};let orphan=rr.iter().rev().find(|q|q.event["t"]=="session/message").is_some_and(|q|q.event["round"]==i&&q.event["role"]=="user"&&q.event["body"]==text&&!rr.iter().any(|e|e.seq>q.seq&&e.event["t"]=="runtime/start"));if state=="Idle"{if saved.is_none()&&!(real&&orphan){crate::session::append(r,&i,"user",&text)?;}if !real{let q=crate::session::context(r,&i)?;return Ok(json!({"round":i,"state":"Idle","where":"讨论态","recorded":true,"modelUsed":false,"text":text,"sessionPath":q["path"],"records":q["records"],"badLines":q["badLines"],"recent":q["recent"],"distill":Value::Null,"version":Value::Null,"note":"message recorded offline; use explicit --live or --wire-in for a response"}))}}else if !real{return Ok(json!({"round":i,"state":"Planning","where":"预备态","recorded":false,"modelUsed":false,"held":true,"note":"draft unchanged; explicit --live or --wire-in is required to revise it"}))}let mut x=o.clone();let goal=if state=="Planning"{intent(r,&i)?.1}else{String::new()};x["goal"]=json!(goal);x["runtime"]=json!(text);x["protocol"]=json!("holder");if state=="Planning"{x["plan_path"]=json!(format!("plans/{i}.md"))}x["state"]=if let Some(q)=saved{x["resume"]=json!(true);q.event["bindingState"].as_object().map(|_|q.event["bindingState"].clone()).ok_or_else(||Error::new("older holder request lacks exact initial binding state; review before a new session"))?}else{let mut state=crate::assemble::initial_state(r,&x)?;state["roundId"]=json!(i);state};let driver=model::drive(r,"round",&x)?;if driver["done"]!=true{return Ok(json!({"round":i,"state":state,"ok":false,"driver":driver,"reviewRequired":driver["stopped"].as_str().is_some_and(|s|s.starts_with("ambiguous")),"note":"holder did not complete; no new understanding/draft approved"}))}if state=="Planning"{let body=plan_artifact(r,&i,s(&driver,"session")?)?.ok_or_else(||Error::new("holder completed without a current-session plan artifact"))?;let mut out=land_plan(r,&i,&c,&intent(r,&i)?.0,&goal,&json!(body),Some(s(&driver,"session")?))?;out["where"]=json!("预备态");out["modelUsed"]=json!(true);out["driver"]=driver;out["text"]=json!(text);journal::append(r,"round",json!({"t":"say/end","round":i,"session":out["driver"]["session"]}))?;return Ok(out)}let said=driver["text"].as_str().unwrap_or("").trim();let version=if said.is_empty(){Value::Null}else{let sid=s(&driver,"session")?;crate::session::finish(r,&i,said,sid)?};let q=crate::session::context(r,&i)?;if said.is_empty(){journal::append(r,"round",json!({"t":"say/end","round":i,"session":driver["session"]}))?;}Ok(json!({"round":i,"state":"Idle","where":"讨论态","text":text,"modelUsed":true,"sessionPath":q["path"],"records":q["records"],"badLines":q["badLines"],"recent":q["recent"],"distill":if said.is_empty(){Value::Null}else{json!(said)},"version":version,"driver":driver}))}
pub fn status(r:&Path,o:&Value)->Result<Value>{crate::probe::status(r,o)}
#[cfg(test)]mod tests{use super::*;#[test]fn transition_edges_fail_closed(){assert!(edge("Idle","Planning"));assert!(edge("Working","Aborted"));assert!(!edge("Idle","Committed"));assert!(!edge("Rebuilding","Planning"));}#[test]fn contract_boundary_validation(){let c=json!({"actions":{"test":{"argv":["true"]}}});let sp=json!([{"goal":"g","ownedPaths":["a"],"assertions":[{"name":"n","action":"test"}]}]);assert!(build(&c,"r1","abc",&sp).is_ok());let mut bad=sp.clone();bad[0]["ownedPaths"]=json!(["../a"]);assert!(build(&c,"r1","abc",&bad).is_err());assert!(build(&c,"r1","abc",&json!([sp[0].clone(),sp[0].clone()])).is_err());bad=sp;bad[0]["assertions"]=json!([]);assert!(build(&c,"r1","abc",&bad).is_err());}}
#[cfg(test)]mod resolve_retry_tests{use super::*;#[test]fn genuine_conflict_stages_are_resolved_without_touching_host(){let d=tempfile::tempdir().unwrap();assert!(std::process::Command::new("git").args(["init","-q","-b","main"]).arg(d.path()).status().unwrap().success());let g=Git::open(d.path()).unwrap();let mut m=BTreeMap::new();let baseentry=crate::git::Entry{kind:"file".into(),mode:0o100644,id:g.put_blob(b"base\n").unwrap()};m.insert("a".into(),baseentry);let base=g.commit_tree(&g.put_tree(&m).unwrap(),&[],"base").unwrap();g.advance("refs/heads/main",&base,None).unwrap();util::replace_leaf(&d.path().join("a"),Some(&util::Leaf{mode:0o100644,bytes:b"base\n".to_vec()})).unwrap();let mut commits=vec![];for text in [b"left\n".as_slice(),b"right\n".as_slice()]{m.get_mut("a").unwrap().id=g.put_blob(text).unwrap();commits.push(g.commit_tree(&g.put_tree(&m).unwrap(),std::slice::from_ref(&base),"branch").unwrap());}let f=merge::fold(&g,&base,&commits).unwrap();assert_eq!(f["kind"],"conflict");assert_eq!(f["conflicts"][0]["path"],"a");assert_eq!(f["conflicts"][0]["stages"].as_array().unwrap().len(),3);let cfg=json!({"actions":{"ok":{"argv":["/usr/bin/true"]}}});let cs=vec![json!({"kind":"implement","id":"r1.implement.1","ownedPaths":["a"],"assertions":[{"name":"n","action":"ok"}]})];let out=resolve_fold(d.path(),"r1",&cfg,&cs,f,&json!({})).unwrap();assert_eq!(out["kind"],"folded");let t=g.tree(out["tree"].as_str().unwrap()).unwrap();assert_eq!(g.blob(&t["a"].id).unwrap(),b"right\n");assert_eq!(g.resolve("refs/heads/main").unwrap(),Some(base));assert_eq!(util::leaf(&d.path().join("a")).unwrap().unwrap().bytes,b"base\n");assert!(!d.path().join(".git/index").exists());}#[test]fn retry_limits_reject_unknown_or_unbounded_values(){assert_eq!(retry_limit(&json!({})).unwrap(),1);assert_eq!(retry_limit(&json!({"retry":"0"})).unwrap(),0);for v in [json!(-1),json!(65),json!(1.5),json!("1x"),json!(true)]{assert!(retry_limit(&json!({"retry":v})).is_err())}}}
#[cfg(test)]mod orchestration_tests{use super::*;use std::sync::atomic::{AtomicUsize,Ordering};struct Checker{calls:AtomicUsize,fail_first:bool}impl Verify for Checker{fn run(&self,_:&Path,_:&str,argv:&[String],opts:&Value)->Result<Value>{assert_eq!(argv,["/usr/bin/true"]);assert_eq!(opts["mode"],"read-only");let n=self.calls.fetch_add(1,Ordering::SeqCst);Ok(json!({"exit":if self.fail_first&&n==0{1}else{0},"denied":false}))}}fn fixture()->(tempfile::TempDir,Git,String,Value){let d=tempfile::tempdir().unwrap();assert!(std::process::Command::new("git").args(["init","-q","-b","main"]).arg(d.path()).status().unwrap().success());let g=Git::open(d.path()).unwrap();let t=g.put_tree(&BTreeMap::new()).unwrap();let b=g.commit_tree(&t,&[],"base").unwrap();g.advance("refs/heads/main",&b,None).unwrap();let c=json!({"round":{"id":"r1"},"actions":{"ok":{"argv":["/usr/bin/true"]}}});util::atomic_write(&d.path().join(".fugue/config"),&serde_json::to_vec(&c).unwrap()).unwrap();(d,g,b,c)}fn assignment(p:&str)->Value{json!({"goal":format!("write {p}"),"ownedPaths":[p],"deliverables":[{"path":p,"form":"file"}],"assertions":[{"name":"ok","action":"ok"}]})}#[test]fn failed_verification_retries_workers_and_replaces_candidate_before_advancing(){let(d,g,b,c)=fixture();command(d.path(),"new",&["goal".into()],&json!({"split":[assignment("a")]})).unwrap();let checker=Checker{calls:AtomicUsize::new(0),fail_first:true};let z=work_with(d.path(),"r1",&c,&json!({"retry":1}),&checker).unwrap();assert_eq!(z["ok"],true);assert_eq!(z["retries"],1);assert_eq!(checker.calls.load(Ordering::SeqCst),2);let es=rows(d.path(),"r1").unwrap();assert_eq!(es.iter().filter(|e|e["t"]=="merge/candidate").count(),2);assert_eq!(es.iter().filter(|e|e["t"]=="merge/invalidate").count(),1);assert_eq!(es.iter().filter(|e|e["t"]=="advance/begin").count(),1);assert_eq!(es.iter().filter(|e|e["t"]=="round/state"&&e["from"]=="Verifying"&&e["to"]=="Working").count(),1);assert_ne!(g.resolve("refs/heads/main").unwrap(),Some(b));assert!(d.path().join("a").is_file());assert!(!d.path().join(".git/index").exists());}#[test]fn investigator_evidence_stays_off_main_while_implementation_advances(){let(d,g,_,c)=fixture();let investigate=json!({"kind":"investigate","question":"check facts","evidenceRequired":[{"note":"facts"}],"seed":[]});command(d.path(),"new",&["goal".into()],&json!({"split":[investigate,assignment("answer")]})).unwrap();let checker=Checker{calls:AtomicUsize::new(0),fail_first:false};let z=work_with(d.path(),"r1",&c,&json!({"retry":0}),&checker).unwrap();assert_eq!(z["ok"],true);let main=g.resolve("refs/heads/main").unwrap().unwrap();let tree=g.tree(&main).unwrap();assert!(tree.contains_key("answer"));assert!(tree.keys().all(|p|!p.starts_with("evidence/")));let evidence=view::View::load(d.path(),"agent/r1/1",None).unwrap();assert!(evidence.read("evidence/agent/r1/1/facts").unwrap().is_some());assert!(!d.path().join("evidence").exists());assert!(!d.path().join(".git/index").exists());}#[test]fn overlapping_approved_workers_resolve_actual_git_conflict_before_verification(){let(d,g,_,c)=fixture();command(d.path(),"new",&["goal".into()],&json!({"split":[assignment("a"),assignment("a")]})).unwrap();let checker=Checker{calls:AtomicUsize::new(0),fail_first:false};let z=work_with(d.path(),"r1",&c,&json!({"retry":0}),&checker).unwrap();assert_eq!(z["ok"],true);assert_eq!(z["fold"]["resolutions"],1);assert!(rows(d.path(),"r1").unwrap().iter().any(|e|e["t"]=="resolve/issue"));let head=g.resolve("refs/heads/main").unwrap().unwrap();let t=g.tree(&head).unwrap();let bytes=g.blob(&t["a"].id).unwrap();assert!(String::from_utf8(bytes).unwrap().contains("r1.implement.2"));assert!(!d.path().join(".git/index").exists());}}

#[cfg(test)]mod parallel_tests{use super::*;use std::sync::{Barrier,atomic::{AtomicUsize,Ordering}};
#[test]fn rendezvous_proves_concurrent_admission_and_join_before_error_return(){let b=Barrier::new(3);let arrived=AtomicUsize::new(0);let finished=AtomicUsize::new(0);let z=parallel_batch(&[json!(0),json!(1),json!(2)],|v|{arrived.fetch_add(1,Ordering::SeqCst);b.wait();assert_eq!(arrived.load(Ordering::SeqCst),3);finished.fetch_add(1,Ordering::SeqCst);if v==0{Err(Error::new("expected"))}else{Ok(v.clone())}});assert_eq!(finished.load(Ordering::SeqCst),3);assert_eq!(z.len(),3);assert!(z[0].is_err());assert_eq!(z[1].as_ref().unwrap(),&json!(1));assert_eq!(z[2].as_ref().unwrap(),&json!(2));}
#[test]fn panic_is_joined_and_sanitized_without_exposing_private_payload(){let done=AtomicUsize::new(0);let z=parallel_batch(&[json!(0),json!(1)],|v|{if v==0{panic!("secret-value")};done.fetch_add(1,Ordering::SeqCst);Ok(v.clone())});assert_eq!(done.load(Ordering::SeqCst),1);assert!(z[0].as_ref().unwrap_err().message.contains("review durable"));assert!(!z[0].as_ref().unwrap_err().message.contains("secret-value"));assert!(z[1].is_ok());}
}

#[cfg(test)]mod holder_artifact_tests{use super::*;#[test]fn old_artifact_cannot_substitute_for_current_holder_exit_but_resumed_session_writes_count(){let d=tempfile::tempdir().unwrap();assert!(std::process::Command::new("git").args(["init","-q","-b","main"]).arg(d.path()).status().unwrap().success());let g=Git::open(d.path()).unwrap();let tree=g.put_tree(&BTreeMap::new()).unwrap();let base=g.commit_tree(&tree,&[],"base").unwrap();g.advance("refs/heads/main",&base,None).unwrap();let mut v=view::View::load(d.path(),"round",None).unwrap();v.write("plans/r1.md",b"old",None).unwrap();journal::append(d.path(),"round",json!({"t":"runtime/start","session":"s2"})).unwrap();assert_eq!(plan_artifact(d.path(),"r1","s2").unwrap(),None);journal::append(d.path(),"round",json!({"t":"holder/plan","body":"{\"plan\":\"new inline\"}"})).unwrap();assert_eq!(plan_artifact(d.path(),"r1","s2").unwrap(),Some("new inline".into()));let mut v=view::View::load(d.path(),"round",None).unwrap();v.write("plans/r1.md",b"current file",None).unwrap();journal::append(d.path(),"round",json!({"t":"runtime/step","session":"s2"})).unwrap();assert_eq!(plan_artifact(d.path(),"r1","s2").unwrap(),Some("current file".into()));assert!(plan_artifact(d.path(),"r1","unknown").is_err());}}
